;; curriculum: Algebra-1 (gr 9) — local maximum; prerequisites: valley
;; math target: the summit is where the slope changes from positive to negative; there the tangent is flat.

app riya-level-mountain "1.1.0"
"riya level 7 · The Mountain — extrema of a bell curve. Climb the hill, touch the flat summit, ride a +k lift to a false local max, then thread the narrow right tail. Catch 5 ★! Composed from std-platformer-body + std-objective-flow + std-fx-particles + std-pickup + std-tutorial-overlay, rendered through math-canvas so the function stays visible. Rebound into the riya-game-platformer organism (menu + all worlds)."

;; @exposure internal

orbital RiyaMountainOrbital {
  uses Body from "std/behaviors/std-platformer-body"
  uses Gate from "std/behaviors/std-objective-flow"
  uses Particles from "std/behaviors/std-fx-particles"
  uses Pickup from "std/behaviors/std-pickup"
  uses Tutorial from "std/behaviors/std-tutorial-overlay"
  uses Genre from "std/behaviors/std-platformer-puzzle"

  type RiyaMountainBody = {
    x : number!
    y : number!
    width : number!
    height : number!
    vx : number
    vy : number
    grounded : boolean
    facingRight : boolean
  }
  type RiyaMountainPlatform = {
    id : string
    x : number!
    y : number!
    width : number!
    height : number!
    type : "ground" | "platform" | "hazard" | "goal"
  }
  type RiyaMountainFx = {
    id : string!
    type : string!
    x : number!
    z : number
    y : number
    message : string
    ttl : number!
    maxTtl : number
    bornAt : number
    space : string
    effect : string
    color : string
    size : number
    vx : number
    vy : number
    vz : number
    particleCount : number
    animation : string
  }
  type RiyaMountainFxPreset = {
    type : string!
    color : string
    color2 : string
    size : number
    shape : string
    count : number
    glow : number
    vy : number
    animation : string
  }
  type RiyaMountainCurveSample = {
    x : number!
    y : number!
  }
  type RiyaMountainCurve = {
    label : string
    color : string
    samples : [RiyaMountainCurveSample]!
    dash : "dashed" | "dotted"
  }
  type RiyaMountainGuide = {
    kind : "vline" | "hline"!
    at : number!
    color : string
    dash : "dashed" | "dotted"
    label : string
  }
  type RiyaMountainPickup = {
    id : string!
    x : number!
    y : number!
    kind : string!
    glyph : string
    message : string
    collected : boolean
  }
  type RiyaMountainLiftMod = {
    id : string!
    x0 : number!
    x1 : number!
    a : number!
    h : number!
    k : number!
  }

  entity RiyaMountainState [runtime, shared] {
    id : string!
    active : boolean = false
    body : RiyaMountainBody = { x: -7, y: 1, width: 0.6, height: 0.6, vx: 0, vy: 0, grounded: false, facingRight: true }
    fell : boolean = false
    hazardId : string = ""
    goalId : string = ""
    skating : boolean = false
    pickups : [RiyaMountainPickup] = []
    pickupCompleted : boolean = false
    total : number = 0
    score : number = 0
    objectivesLeft : number = 0
    result : string = "none"
    fx : [RiyaMountainFx] = []
    celebrated : boolean = false
    seq : number = 0
    lastText : string = ""
    zoneId : string = "mountain"
    platforms : [RiyaMountainPlatform] = []
    curves : [RiyaMountainCurve] = []
    slopeCurves : [RiyaMountainCurve] = []
    guides : [RiyaMountainGuide] = []
  }

  entity MountainTutorialData [runtime] {
    id : string!
    step : number = 0
    done : boolean = false
  }

  trait MountainBody = Body.traits.PlatformerBody -> RiyaMountainState {
    events {
      STEER: MOUNTAIN_STEER
      JUMP: MOUNTAIN_LEAP
      PLACE: MOUNTAIN_PLACE
      RESTART: MOUNTAIN_RESTART
      CURVE_MOD_ADD: MOUNTAIN_CURVE_MOD_ADD
      SET_TUNING: MOUNTAIN_SET_TUNING
      SET_PLATFORMS: MOUNTAIN_SET_PLATFORMS
      SET_SKATE_CURVE: MOUNTAIN_SET_SKATE_CURVE
      BODY_JUMPED: MOUNTAIN_JUMPED
      BODY_LANDED: MOUNTAIN_LANDED
      BODY_HAZARD: MOUNTAIN_HAZARD
      BODY_GOAL: MOUNTAIN_GOAL
      BODY_FELL: MOUNTAIN_FELL
      BODY_SKATE_START: MOUNTAIN_SKATE_ON
      BODY_SKATE_END: MOUNTAIN_SKATE_OFF
    }
    config {
      running: true
      spawn: { x: -7, y: 1, width: 0.6, height: 0.6, vx: 0, vy: 0, grounded: false, facingRight: true }
      gravity: -24
      jumpStrength: 11
      moveSpeed: 5
      maxFallSpeed: 14
      xMin: -10
      xMax: 9.4
      killY: -3
      skate: true
      curveModsEnabled: true
      skateSnap: 0.9
    }
  }

  trait MountainGate = Gate.traits.ObjectiveFlow -> RiyaMountainState {
    events {
      PROGRESS: MOUNTAIN_PROGRESS
      GAME_END: MOUNTAIN_GAME_END
      RESTART: MOUNTAIN_RESTART
    }
    config { running: true }
  }

  trait MountainFx = Particles.traits.FxParticles -> RiyaMountainState {
    events {
      BURST: MOUNTAIN_BURST
    }
    config { running: true }
  }

  trait MountainTutorialPreview -> MountainTutorialData [interaction, instance] {
    initial: idle
    state idle {
      INIT -> idle
        (render-ui center null)
    }
  }

  trait MountainTutorial = Tutorial.traits.TutorialOverlay -> MountainTutorialData {
    events {
      SHOW: MOUNTAIN_TUTORIAL_SHOW
      TUTORIAL_DONE: MOUNTAIN_TUTORIAL_DONE
    }
    config {
      autoShow: true
      previewTrait: @trait.MountainTutorialPreview
      steps: [
        { id: "intro", title: "The Mountain", body: "The hill has a summit. Climb until the slope flattens, grab +k to build a false peak, then reach every ★." }
      ]
    }
  }

  trait MountainPickup = Pickup.traits.Pickup -> RiyaMountainState {
    events {
      PICKED: MOUNTAIN_PICKED
      COLLECT: MOUNTAIN_COLLECT
      PICKUP_SET_COMPLETED: MOUNTAIN_PICKUP_SET_COMPLETED
      SET_FEATURES: MOUNTAIN_SET_FEATURES
    }
    config {
      running: true
      reachX: 0.7
      reachY: 1.2
    }
  }

  trait MountainLevelData -> @rebindable RiyaMountainState [lifecycle] {
    initial: active

    state active {
      INIT -> active
        (emit RIYA_LEVEL_DATA {
          id: "mountain"
          name: @config.worldName
          equation: @config.equation
          concept: @config.concept
          regionColor: @config.regionColor
          entryY: @config.entryY
          exitY: @config.exitY
          platforms: (array/map @config.platforms (fn p @p))
          stars: (array/map @config.stars (fn s @s))
          skateCurve: (array/map @config.skateCurve (fn c @c))
          curveOverlay: (array/map @config.curveOverlay (fn c @c))
          slopeCurves: (array/map @config.slopeCurves (fn c @c))
          guides: (array/map @config.guides (fn g @g))
          liftMods: (array/map @config.liftMods (fn m @m))
        })
    }

    emits {
      RIYA_LEVEL_DATA -> external {
        id : string!
        name : string!
        equation : string!
        concept : string!
        regionColor : string!
        entryY : number!
        exitY : number!
        platforms : [RiyaMountainPlatform]!
        stars : [RiyaMountainPickup]!
        skateCurve : [RiyaMountainCurveSample]
        curveOverlay : [RiyaMountainCurve]
        slopeCurves : [RiyaMountainCurve]
        guides : [RiyaMountainGuide]
        liftMods : [RiyaMountainLiftMod]
      }
        @description "The zone's canonical static geometry + pedagogy, broadcast once on INIT in zone-local coordinates. This atom's own play trait consumes it to seed the body/pickup authorities and the render; the riya open-world organism consumes the same event and applies its zone offset, so standalone and composed can never diverge."
        @tier "domain"
    }

    config {
      worldName : string = "The Mountain"
        @label "World Name"
        @description "This world's display name — the open world's zone banner reads it from RIYA_LEVEL_DATA."
        @tier "presentation"
      equation : string = "y = 5·e^(−(x+1)²/10) + 0.5"
        @label "Equation"
        @description "The zone's skate/banner equation."
        @tier "presentation"
      concept : string = "the summit is the global maximum (slope 0); a +k lift creates a false local max; the right tail narrows to a steep finale"
        @label "Concept"
        @description "The world's one math idea."
        @tier "presentation"
      regionColor : string = "#38bdf8"
        @label "Region Color"
        @description "Zone band accent in the open world."
        @tier "presentation"
      entryY : number = 0.54
        @label "Entry Y"
        @description "Run-surface height at the zone's left edge; the open world stitches its incoming bridge to this."
        @tier "domain"
      exitY : number = 1.52
        @label "Exit Y"
        @description "Run-surface height at the zone's right edge; the open world stitches its outgoing bridge to this."
        @tier "domain"
      platforms : [RiyaMountainPlatform] = [
        { id: "m-8", x: -8, y: -2, width: 2, height: 2.54, type: "ground" }
        { id: "m-7", x: -6, y: -2, width: 2, height: 2.64, type: "ground" }
        { id: "m-6", x: -4, y: -2, width: 2, height: 2.91, type: "ground" }
        { id: "m-5", x: -2, y: -2, width: 2, height: 3.51, type: "ground" }
        { id: "m-4", x: 0, y: -2, width: 2, height: 4.53, type: "ground" }
        { id: "m-3", x: 2, y: -2, width: 2, height: 5.85, type: "ground" }
        { id: "m-2", x: 4, y: -2, width: 2, height: 5.02, type: "ground" }
        { id: "m-1", x: 6, y: -2, width: 2, height: 3.64, type: "ground" }
        { id: "m0", x: 8, y: -2, width: 2, height: 3.52, type: "ground" }
      ]
        @label "Platforms"
        @description "Canonical terrain — seeds the body authority's collision AND the canvas bars via RIYA_LEVEL_DATA. Bars sample y = 5·e^(−(x+1)²/10) + 0.5."
        @tier "domain"
      stars : [RiyaMountainPickup] = [
