  trait RiyaMountainGenre = Genre.traits.PlatformerPuzzle -> RiyaMountainState {
    config {
      agencyTrait: @trait.MountainBody
      challengeTrait: @trait.MountainBody
      goalTrait: @trait.MountainGate
      rewardTrait: @trait.MountainPickup
      feedbackTrait: @trait.MountainFx
    }
  }

  trait RiyaMountainPlay -> @rebindable RiyaMountainState [interaction, instance] {
    initial: idle

    state idle {
      INIT -> idle
        (set @entity.active true)
        (set @entity.celebrated false)
        (set @entity.score 0)
        (emit MOUNTAIN_RESTART { id: "board" })
        (render-ui main {
          type: game-shell
          appName: (str/concat "riya · " @config.worldName)
          fontFamily: "future-narrow"
          children: [ {
            type: math-canvas
            width: @config.width
            height: @config.height
            xMin: @config.xMin
            xMax: @config.xMax
            yMin: @config.yMin
            yMax: @config.yMax
            showTickLabels: true
            showCurveLabels: true
            keyMap: { ArrowLeft: "MOUNTAIN_LEFT", KeyA: "MOUNTAIN_LEFT", ArrowRight: "MOUNTAIN_RIGHT", KeyD: "MOUNTAIN_RIGHT", ArrowUp: "MOUNTAIN_JUMP", KeyW: "MOUNTAIN_JUMP", Space: "MOUNTAIN_JUMP" }
            keyUpMap: { ArrowLeft: "MOUNTAIN_STOP", KeyA: "MOUNTAIN_STOP", ArrowRight: "MOUNTAIN_STOP", KeyD: "MOUNTAIN_STOP" }
            curves: (array/concat
              (array/map @entity.curves (fn c (object/merge @c { color: (if @entity.skating @config.curveSkateColor (object/get @c color)) })))
              @entity.slopeCurves)
            guides: @entity.guides
            bars: (array/map @entity.platforms (fn p { x: (object/get @p x), width: (object/get @p width), y0: (object/get @p y), y1: (+ (object/get @p y) (object/get @p height)), color: @config.terrainColor, opacity: 0.85 }))
            points: (array/concat
              (array/map (array/filter @entity.pickups (fn p (== (object/get @p collected) false))) (fn f { x: (object/get @f x), y: (object/get @f y), label: (object/get @f glyph), color: (if (== (object/get @f kind) "lift") "#f472b6" @config.starColor), radius: 9 }))
              (array/concat
                [ { x: (+ @entity.body.x 0.3), y: (+ @entity.body.y 0.3), label: "riya", color: @config.riyaColor, radius: 6 } ]
                (array/concat
                  (if @entity.skating [ { x: (+ @entity.body.x 0.3), y: (+ @entity.body.y 1.4), label: (str/concat @config.equationText " · x = " (math/round (+ @entity.body.x 0.3) 1)), color: @config.equationColor, radius: 3 } ] [])
                  (if @config.showTelemetry [ { x: (+ @entity.body.x 0.3), y: (+ @entity.body.y 2.2), label: (str/concat "x = " (math/round (+ @entity.body.x 0.3) 1) " · y = " (math/round (+ @entity.body.y 0.3) 1) " · v = " (math/round (math/hypot @entity.body.vx @entity.body.vy) 1)), color: @config.equationColor, radius: 3 } ] []))))
            drawables: [ {
              type: "draw-fx-layer"
              items: @entity.fx
              tickMs: 500
              presets: @config.fxPresets
            } ]
            vectors: [ { x: (+ @entity.body.x 0.3), y: (+ @entity.body.y @config.arrowOffsetY), vx: (* @entity.body.vx @config.arrowScale), vy: (* @entity.body.vy @config.arrowScale), color: @config.riyaColor, label: "v" } ]
          } ]
        })
        (render-ui hud-top {
          type: stack
          direction: horizontal
          justify: center
          className: "p-3"
          children: [ { type: game-hud, variant: "floating", stats: [ { label: "★", value: @entity.score } ] } ]
        })
        (render-ui hud-bottom {
          type: stack
          direction: horizontal
          justify: start
          className: "p-4"
          children: [ { type: control-grid, kind: "dpad", visibility: "auto", directionEvents: { left: "MOUNTAIN_LEFT", right: "MOUNTAIN_RIGHT", up: "MOUNTAIN_JUMP" }, directionReleaseEvents: { left: "MOUNTAIN_STOP", right: "MOUNTAIN_STOP" } } ]
        })

      RIYA_LEVEL_DATA -> idle when (== @payload.id "mountain")
        (set @entity.curves @payload.curveOverlay)
        (set @entity.slopeCurves @payload.slopeCurves)
        (set @entity.guides @payload.guides)
        (set @entity.objectivesLeft (array/len @payload.stars))
        (emit MOUNTAIN_SET_PLATFORMS { platforms: @payload.platforms })
        (emit MOUNTAIN_SET_SKATE_CURVE { curve: @payload.skateCurve })
        (emit MOUNTAIN_SET_FEATURES { features: @payload.stars })

      MOUNTAIN_LEFT -> idle when (and (== @entity.active true) (== @entity.result "none"))
        (emit MOUNTAIN_STEER { dir: -1 })

      MOUNTAIN_RIGHT -> idle when (and (== @entity.active true) (== @entity.result "none"))
        (emit MOUNTAIN_STEER { dir: 1 })

      MOUNTAIN_STOP -> idle when (== @entity.active true)
        (emit MOUNTAIN_STEER { dir: 0 })

      MOUNTAIN_JUMP -> idle when (and (== @entity.active true) (== @entity.result "none"))
        (emit MOUNTAIN_LEAP {})

      MOUNTAIN_FELL -> idle when (== @entity.active true)
        (emit MOUNTAIN_PLACE { x: @config.respawnX, y: @config.respawnY })
        (emit MOUNTAIN_BURST { particles: (array/map [ "fx-mountain-fell" ] (fn fid { id: @fid, type: "info", x: @config.respawnX, z: @config.respawnY, message: "💫", ttl: 3 })) })

      MOUNTAIN_SKATE_ON -> idle when (== @entity.active true)
        (emit MOUNTAIN_BURST { particles: (array/concat
          { id: "narrative-skate", type: "narrative", x: @entity.body.x, z: (+ @entity.body.y 2), y: 0, message: "slope = 0 at the maximum", ttl: 2, maxTtl: 2, bornAt: (time/now), space: "world", effect: "float-text", color: "#a78bfa", size: 0.7, vx: 0, vy: 0, vz: 0, particleCount: 1 }
          {
            id: "fx-mountain-skate",
            type: "info",
            x: @payload.x,
            z: (+ @payload.y 0.6),
            y: 0,
            message: (str/concat @config.equationText " · x = " (math/round (+ @payload.x 0.3) 1)),
            ttl: 4
          }
        ) })
      MOUNTAIN_COLLECT -> idle when (== @entity.active true)
        (set @entity.score @payload.total)
        (set @entity.objectivesLeft (- (array/len @entity.pickups) @payload.total))
        (emit MOUNTAIN_PROGRESS { objectivesLeft: @entity.objectivesLeft, movesLeft: 9999 })
        (render-ui hud-top {
          type: stack
          direction: horizontal
          justify: center
          className: "p-3"
          children: [ { type: game-hud, variant: "floating", stats: [ { label: "★", value: @entity.score } ] } ]
        })

      MOUNTAIN_PICKUP_SET_COMPLETED -> idle when (== @entity.active true)
        (emit MOUNTAIN_BURST { particles: (array/map [ "complete" ] (fn _ { id: "narrative-complete", type: "narrative", x: 0, z: 8, y: 0, message: "summit = local maximum", ttl: 3, maxTtl: 3, bornAt: (time/now), space: "world", effect: "float-text", color: "#facc15", size: 0.9, vx: 0, vy: 0, vz: 0, particleCount: 1 })) })
        (emit MOUNTAIN_PROGRESS { objectivesLeft: 0, movesLeft: 9999 })
      MOUNTAIN_GAME_END -> idle when (and (== @payload.result "won") (== @entity.celebrated false))
        (set @entity.celebrated true)
        (emit RIYA_LEVEL_SOLVED { level: "mountain" })

      MOUNTAIN_TUTORIAL_DONE -> idle
        (emit MOUNTAIN_BURST { particles: (array/map [ "tutorial" ] (fn _ { id: "narrative-tutorial", type: "narrative", x: 0, z: 10, y: 0, message: "climb up, flatten at the top, descend", ttl: 3, maxTtl: 3, bornAt: (time/now), space: "world", effect: "float-text", color: "#38bdf8", size: 0.9, vx: 0, vy: 0, vz: 0, particleCount: 1 })) })
    }

    ticks {
      renderTick every 100ms when (== @entity.active true)
        (render-ui main {
          type: game-shell
          appName: (str/concat "riya · " @config.worldName)
          fontFamily: "future-narrow"
          children: [ {
            type: math-canvas
            width: @config.width
            height: @config.height
            xMin: @config.xMin
            xMax: @config.xMax
            yMin: @config.yMin
            yMax: @config.yMax
            showTickLabels: true
            showCurveLabels: true
            keyMap: { ArrowLeft: "MOUNTAIN_LEFT", KeyA: "MOUNTAIN_LEFT", ArrowRight: "MOUNTAIN_RIGHT", KeyD: "MOUNTAIN_RIGHT", ArrowUp: "MOUNTAIN_JUMP", KeyW: "MOUNTAIN_JUMP", Space: "MOUNTAIN_JUMP" }
            keyUpMap: { ArrowLeft: "MOUNTAIN_STOP", KeyA: "MOUNTAIN_STOP", ArrowRight: "MOUNTAIN_STOP", KeyD: "MOUNTAIN_STOP" }
            curves: (array/concat
              (array/map @entity.curves (fn c (object/merge @c { color: (if @entity.skating @config.curveSkateColor (object/get @c color)) })))
              @entity.slopeCurves)
            guides: @entity.guides
            bars: (array/map @entity.platforms (fn p { x: (object/get @p x), width: (object/get @p width), y0: (object/get @p y), y1: (+ (object/get @p y) (object/get @p height)), color: @config.terrainColor, opacity: 0.85 }))
            points: (array/concat
              (array/map (array/filter @entity.pickups (fn p (== (object/get @p collected) false))) (fn f { x: (object/get @f x), y: (object/get @f y), label: (object/get @f glyph), color: (if (== (object/get @f kind) "lift") "#f472b6" @config.starColor), radius: 9 }))
              (array/concat
                [ { x: (+ @entity.body.x 0.3), y: (+ @entity.body.y 0.3), label: "riya", color: @config.riyaColor, radius: 6 } ]
                (array/concat
                  (if @entity.skating [ { x: (+ @entity.body.x 0.3), y: (+ @entity.body.y 1.4), label: (str/concat @config.equationText " · x = " (math/round (+ @entity.body.x 0.3) 1)), color: @config.equationColor, radius: 3 } ] [])
                  (if @config.showTelemetry [ { x: (+ @entity.body.x 0.3), y: (+ @entity.body.y 2.2), label: (str/concat "x = " (math/round (+ @entity.body.x 0.3) 1) " · y = " (math/round (+ @entity.body.y 0.3) 1) " · v = " (math/round (math/hypot @entity.body.vx @entity.body.vy) 1)), color: @config.equationColor, radius: 3 } ] []))))
            drawables: [ {
              type: "draw-fx-layer"
              items: @entity.fx
              tickMs: 500
              presets: @config.fxPresets
            } ]
            vectors: [ { x: (+ @entity.body.x 0.3), y: (+ @entity.body.y @config.arrowOffsetY), vx: (* @entity.body.vx @config.arrowScale), vy: (* @entity.body.vy @config.arrowScale), color: @config.riyaColor, label: "v" } ]
          } ]
        })
    }

    emits {
      MOUNTAIN_LEFT -> external {
        id : string
      }
        @description "Run-left intent from ArrowLeft/KeyA keydown or d-pad (forwarded as STEER dir −1)."
        @tier "domain"
      MOUNTAIN_RIGHT -> external {
        id : string
      }
        @description "Run-right intent from ArrowRight/KeyD keydown or d-pad (forwarded as STEER dir +1)."
        @tier "domain"
      MOUNTAIN_STOP -> external {
        id : string
      }
        @description "Left/right key release (keyUpMap or d-pad release); forwarded as STEER dir 0."
        @tier "domain"
      MOUNTAIN_JUMP -> external {
        id : string
      }
        @description "Jump intent from Space/ArrowUp/KeyW or d-pad up; forwarded as the body authority's renamed JUMP (MOUNTAIN_LEAP), which accepts it only while grounded."
        @tier "domain"
      MOUNTAIN_STEER -> external {
        dir : number!
      }
        @description "Renamed STEER consumed by this world's platformer-body authority (−1/0/+1 × moveSpeed)."
        @tier "domain"
      MOUNTAIN_LEAP -> external {
        id : string
      }
        @description "Renamed JUMP consumed by this world's platformer-body authority (grounded-gated vertical kick)."
        @tier "domain"
      MOUNTAIN_PLACE -> external {
        x : number!
        y : number!
      }
        @description "Renamed PLACE consumed by this world's platformer-body authority; the pit-fall respawn teleport."
        @tier "domain"
      MOUNTAIN_FELL -> external {
        x : number!
        y : number!
      }
        @description "Pit-fall signal from this world's platformer-body authority (renamed BODY_FELL); respawns riya at her spawn with every star kept."
        @tier "domain"
      MOUNTAIN_SKATE_ON -> external {
        x : number!
        y : number!
        slope : number!
      }
        @description "Skate-engage signal from this world's platformer-body authority (renamed BODY_SKATE_START); riya touched the hill curve — fires the slope fx burst."
        @tier "domain"
      MOUNTAIN_PICKED -> external {
        id : string!
        kind : string!
        x : number!
        y : number!
        glyph : string
        message : string
      }
        @description "A pickup was collected (renamed PICKED from std-pickup); carries kind so the board can apply boost effects like curve lifts."
        @tier "domain"
      MOUNTAIN_COLLECT -> external {
        total : number!
      }
        @description "Running pickup count (renamed COLLECT from std-pickup); updates score/objectives and forwards to the objective-flow gate."
        @tier "domain"
      MOUNTAIN_PICKUP_SET_COMPLETED -> external {
      }
        @description "Every pickup in the set is collected (renamed PICKUP_SET_COMPLETED from std-pickup)."
        @tier "domain"
      MOUNTAIN_SET_TUNING -> external {
        jumpStrength : number
        moveSpeed : number
        gravity : number
      }
        @description "Renamed SET_TUNING consumed by the platformer-body authority; applies live body tuning overrides."
        @tier "domain"
      MOUNTAIN_RESTART -> external {
        id : string
      }
        @description "Reseed broadcast consumed by this world's platformer-body/objective-flow authorities (renamed RESTART)."
        @tier "domain"
      MOUNTAIN_BURST -> external {
        particles : [RiyaMountainFx]
      }
        @description "Particle batch spawned on star pickup or pit respawn; fx-particles fades it."
        @tier "domain"
      MOUNTAIN_PROGRESS -> external {
        objectivesLeft : number!
        movesLeft : number!
      }
        @description "Sparse progress signal emitted by the gameTick only when a star is collected; the objective-flow gate resolves won from it."
        @tier "domain"
      MOUNTAIN_GAME_END -> external {
        result : string!
      }
        @description "Win-gate resolution from this world's objective-flow authority (renamed GAME_END); won clears the level."
        @tier "domain"
      RIYA_LEVEL_SOLVED -> external {
        level : string
      }
        @description "Every ★ captured — the win gate resolved won (guarded by celebrated so the gate's repeated GAME_ENDs fire it once)."
        @tier "domain"
      MOUNTAIN_SET_PLATFORMS -> external {
        platforms : [RiyaMountainPlatform]!
      }
        @description "Renamed SET_PLATFORMS consumed by this world's platformer-body authority; forwards the canonical RIYA_LEVEL_DATA terrain to collision."
        @tier "domain"
      MOUNTAIN_SET_SKATE_CURVE -> external {
        curve : [RiyaMountainCurveSample]!
      }
        @description "Renamed SET_SKATE_CURVE consumed by this world's platformer-body authority; forwards the canonical RIYA_LEVEL_DATA bell-curve surface to the skate sampler."
        @tier "domain"
      MOUNTAIN_SET_FEATURES -> external {
        features : [RiyaMountainPickup]!
      }
        @description "Renamed SET_FEATURES consumed by this world's pickup authority; forwards the canonical RIYA_LEVEL_DATA stars + lift pad."
        @tier "domain"
    }

    listens {
      MOUNTAIN_TUTORIAL_DONE { id : string }
      RIYA_LEVEL_DATA {
        id : string!
        name : string!
        equation : string!
        concept : string!
        regionColor : string!
        entryY : number!
        exitY : number!
        platforms : [RiyaMountainPlatform]!
        stars : [RiyaMountainPickup]!
        skateCurve : [RiyaMountainCurveSample]
        curveOverlay : [RiyaMountainCurve]
        slopeCurves : [RiyaMountainCurve]
        guides : [RiyaMountainGuide]
        liftMods : [RiyaMountainLiftMod]
      }
    }

    config {
      equationText : string = "y = 5·e^(−(x+1)²/10) + 0.5"
        @label "Equation Text"
        @description "Equation of this world's curve, shown by the skate fx burst and the floating label that follows riya while she skates the graph."
        @tier "presentation"
      equationColor : string = "#7dd3fc"
        @label "Equation Color"
        @description "Color of the floating equation label that follows riya while she skates."
        @tier "presentation"
      curveSkateColor : string = "#f0abfc"
        @label "Curve Skate Color"
        @description "Curve trace color while riya is skating the graph (the faint curveOverlay color otherwise)."
        @tier "presentation"
      respawnX : number = -7
        @label "Respawn X"
        @description "X riya teleports to after a pit fall (matches MountainBody spawn.x)."
        @tier "domain"
      respawnY : number = 1
        @label "Respawn Y"
        @description "Y riya teleports to after a pit fall (matches MountainBody spawn.y)."
        @tier "domain"
      reachRadius : number = 0.7
        @label "Reach Radius"
        @description "Manhattan distance from riya's center at which the gameTick counts a star as collected."
        @tier "domain"
      objectiveText : string = ""
        @label "Objective Text"
        @description "HUD hint (kept empty — the curve geometry and FX carry the objective)."
        @tier "presentation"
      worldName : string = "The Mountain"
        @label "World Name"
        @description "This world's display name, shown in the game-shell title chip as \"riya · <worldName>\"."
        @tier "presentation"
      showTelemetry : boolean = false
        @label "Show Telemetry"
        @description "When true, draws a compact x/y/v readout on the canvas near riya (teaching/debug aid). Off keeps the HUD to score only."
        @tier "domain"
      conceptText : string = "the summit is the global maximum (slope 0); a +k lift creates a false local max; the right tail narrows to a steep finale"
        @label "Concept Text"
        @description "The world's one math idea — metadata for the picker/factory, not rendered in-game."
        @tier "presentation"
      riyaColor : string = "#dc2626"
        @label "Riya Color"
        @description "Marker color for riya the dot."
        @tier "presentation"
      starColor : string = "#f59e0b"
        @label "Star Color"
        @description "Marker color for uncollected stars."
        @tier "presentation"
      terrainColor : string = "#78716c"
        @label "Terrain Color"
        @description "Bar color for the ground/platform bars."
        @tier "presentation"
      arrowOffsetY : number = 1.9
        @label "Arrow Offset Y"
        @description "World units above the body center where the velocity vector arrow originates, so it floats above the player sprite."
        @tier "presentation"
      arrowScale : number = 0.5
        @label "Arrow Scale"
        @description "Scale factor for the velocity vector arrow, kept short so it does not dip behind the sprite."
        @tier "presentation"
      fxPresets : [RiyaMountainFxPreset] = [ { type: "info", color: "#38bdf8", color2: "#0c4a6e", size: 0.8, shape: "puff", count: 4 }, { type: "pickup", color: "#ffe066", color2: "#ffffff", size: 1.0, shape: "spark", count: 5, glow: 0.12, vy: -0.1 }, { type: "narrative", color: "#38bdf8", size: 1.4, shape: "ring", count: 1, glow: 0.1 } ]
        @label "Fx Presets"
        @description "Look table for world-space particle effects rendered by the draw-fx-layer."
        @tier "presentation"
      xMin : number = -10
        @label "X Min"
        @description "Left edge of the visible math window."
        @tier "presentation"
      xMax : number = 10
        @label "X Max"
        @description "Right edge of the visible math window."
        @tier "presentation"
      yMin : number = -2
        @label "Y Min"
        @description "Bottom edge of the visible math window."
        @tier "presentation"
      yMax : number = 12
        @label "Y Max"
        @description "Top edge of the visible math window."
        @tier "presentation"
      width : number = 800
        @label "Canvas Width"
        @description "math-canvas display width in px."
        @tier "presentation"
      height : number = 480
        @label "Canvas Height"
        @description "math-canvas display height in px."
        @tier "presentation"
    }
  }

  trait MountainChallenge -> @rebindable RiyaMountainState [game-core, instance] {
    initial: idle

    state idle {
      MOUNTAIN_PICKED -> idle when (and (== @entity.zoneId @config.zoneId) (== @entity.active true))
        (if (str/endsWith @payload.id "lift-r")
          (do
            (emit MOUNTAIN_CURVE_MOD_ADD { x0: 1, x1: 4.5, a: 1, h: 0, k: 1.8 })
            (emit MOUNTAIN_BURST { particles: (array/concat
              { id: "narrative-lift-r-fact", type: "narrative", x: @payload.x, z: (+ @payload.y 1.8), y: 0, message: "f(x)+1.8", ttl: 2, maxTtl: 2, bornAt: (time/now), space: "world", effect: "float-text", color: "#f472b6", size: 0.7, vx: 0, vy: 0, vz: 0, particleCount: 1 }
              { id: "narrative-lift-r-hint", type: "narrative", x: @payload.x, z: (+ @payload.y 2.3), y: 0, message: "false local max", ttl: 2, maxTtl: 2, bornAt: (time/now), space: "world", effect: "float-text", color: "#a78bfa", size: 0.6, vx: 0, vy: 0, vz: 0, particleCount: 1 }
            ) }))
          (emit MOUNTAIN_BURST { particles: (array/map [ "fx-pickup-" ] (fn fid { id: (str/concat @fid @payload.id), type: "pickup", x: @payload.x, z: @payload.y, message: (if (== @payload.kind "lift") "+k" @payload.glyph), ttl: 2 })) }))
    }

    emits {
      MOUNTAIN_CURVE_MOD_ADD -> external {
        x0 : number!
        x1 : number!
        a : number!
        h : number!
        k : number!
      }
        @description "Renamed CURVE_MOD_ADD consumed by the platformer-body authority; applies the lift pad's +1.8 mod to the skate curve."
        @tier "domain"
      MOUNTAIN_BURST -> external {
        particles : [RiyaMountainFx]
      }
        @description "Particle batch spawned on pickup (generic sparkle or the lift pad's narrative beats); fx-particles fades it."
        @tier "domain"
    }

    listens {
      MOUNTAIN_PICKED { id : string!, kind : string!, x : number!, y : number!, glyph : string, message : string }
    }

    config {
      zoneId : string = "mountain"
        @label "Zone Id"
        @description "The zone this challenge choreography belongs to. Guards compare it against @entity.zoneId, so a composed open world fires it only while riya stands in this zone; standalone the entity default equals this knob and the guard is always true."
        @tier "domain"
    }
  }

  trait RiyaMountainClear -> @rebindable RiyaMountainState [interaction, instance] {
    initial: watching

    state watching {
      INIT -> watching
        (render-ui overlay null)

      RIYA_LEVEL_SOLVED -> watching
        (render-ui overlay {
          type: game-menu
          title: @config.clearTitle
          subtitle: @config.clearSubtitle
          options: [ { id: "next", label: "Next ▶", event: "MOUNTAIN_NEXT", variant: "primary" } ]
        })

      MOUNTAIN_NEXT -> watching
        (render-ui overlay null)
        (navigate @config.nextPath)

      CLOSE -> watching
        (render-ui overlay null)
    }

    listens {
      RIYA_LEVEL_SOLVED { level : string }
      MOUNTAIN_NEXT { id : string }
      CLOSE
    }

    config {
      nextPath : string = "/riya-mountain"
        @label "Next Path"
        @description "Page the clear overlay's Next button navigates to. Standalone default replays this world; riya-game-platformer overrides it with the next world's path."
        @tier "presentation"
      clearTitle : string = "Mountain clear ★"
        @label "Clear Title"
        @description "Overlay title once every star is collected."
        @tier "presentation"
      clearSubtitle : string = "At the summit the slope is zero; the lifted ledge was only a local max."
        @label "Clear Subtitle"
        @description "One-line celebration under the clear title."
        @tier "presentation"
    }
  }

  page "/riya-mountain" as RiyaMountainPage -> MountainLevelData, MountainBody, MountainGate, MountainFx, MountainPickup, MountainTutorial, RiyaMountainGenre, RiyaMountainPlay, MountainChallenge, RiyaMountainClear
}
